type ByteReader interface {
    Read([]byte) (int, error)
}

func ReadFirstByte(reader ByteReader) (byte, error) {
    buffer := make([]byte, 1)
    _, err := reader.Read(buffer)
    if err != nil {
        return 0, err
    }
    return buffer[0], nil
}
